WFJ.Data.add("book", {
  ["3154707e4a1cd458"] = { "Nozdormu:\n\rNozdormu è noto come il Signore del Tempo e il Senza Tempo. Lui e il suo stormo sono color bronzo e mostrano grande astuzia in ogni cosa. L'attenzione di Nozdormu è sempre stata rivolta a raccogliere manufatti del passato, perché poco gli importa delle vicende attuali delle razze mortali, o persino degli affari degli altri Aspetti. La sua indifferenza verso la politica altrui non significa però che resti inerte di fronte agli eventi che accadono nel mondo.", "." },
  ["31887fb2c4a82bc9"] = { "Nessuno dei miei nuovi esperimenti portò alla luce rivelazioni sull'origine della sanguinite. All'epoca l'unico enigma che risolsi fu che la sanguinite non era né viva né morta!\n\nMa fu allora, sull'orlo del fallimento, che arrivò la svolta. Il mio ultimo esperimento prevedeva un becher di vetro dal bordo scheggiato, che lasciava una piccola tacca frastagliata lungo l'orlo. Finito l'esperimento, che ancora una volta non aveva rivelato nulla, andai a pulire il banco di lavoro e mi tagliai con il becher.", "." },
  ["31894f4ddadcbe70"] = { "Kurdran Wildhammer\n\nRinomato combattente di draghi. Maestro dei grifoni del ⟦Aerie Peak=Picco dell'Aquila⟧. Comandante della divisione dei Cavalieri di Grifoni aggregata alla Spedizione dell'⟦Alliance=Alleanza⟧ che marciò su Draenor, il mondo natale degli orchi. Presunto morto.\n\nUdremo i richiami di Sky-Ree nel vento. Udremo il tuo martello tuonare sulle vette dei monti. Cavalca veloce verso l'aldilà, fratello. Le sale dei nostri antenati ti attendono.\n\n- ⟦Falstad Wildhammer=Falstad Granmartello⟧ - Signore del ⟦Aerie Peak=Picco dell'Aquila⟧", "." },
  ["3192ef4c83375499"] = { "Fratello o sorella del mestiere, spero che questa runa ti trovi in buona salute. Volevo prendermi un momento per farti sapere che sono dentro ⟦Anvilmar=Forgiamara⟧, sopra la ⟦Coldridge Valley=Valle Crestafredda⟧.\n\nSo quanto sia importante restare tutti uniti, e in questi tempi di pace tesa è ancora più importante avere vicino quelli della nostra specie. Cercami quando hai tempo.\n\n-Solm Hargrin, istruttore dei ladri", "." },
  ["31ba8f2eb7714aca"] = { "Benché i figli della terra si fossero chiusi ai sussurri malvagi, una terribile maledizione si abbatté sulle loro tribù erranti. Dalle terre nere dell'ovest giunse un'orda di creature assassine: i centauri. Cannibali e predoni, i centauri si avventarono sugli Shu'halo come una piaga. Benché i valorosi e i cacciatori combattessero con la benedizione della Madre Terra nel cuore, i centauri non potevano essere sconfitti.", "." },
})
